    <script>
      function toggleQuest(header) {
        const container = header.parentNode;
        container.classList.toggle('collapsed');
        const isCollapsed = container.classList.contains('collapsed');
        localStorage.setItem('questContainerCollapsed', isCollapsed);
      }

      window.onload = function() {
        const container = document.querySelector('.quest-container');
        const wasExpanded = localStorage.getItem('questContainerCollapsed') === 'false';
        if (wasExpanded) {
          container.classList.remove('collapsed');
        } else {
          container.classList.add('collapsed');
        }
      };
    </script>
  </body>
</html>
